const preguntasRonda = (r) => {
  const pool = BANCO.filter(x => x.r === r).sort(() => Math.random() - .5).slice(0, 3);

  // Baraja opciones y re-etiqueta A/B/C para que la correcta no quede siempre en A.
  const shuffleAndRelabel = (arr, correctKey) => {
    const shuffled = [...arr].sort(() => Math.random() - 0.5);
    const keys = ["A", "B", "C"];
    let newCorrect = correctKey;
    const items = shuffled.map((item, i) => {
      const newKey = keys[i];
      if (String(item.k).toUpperCase() === String(correctKey).toUpperCase()) newCorrect = newKey;
      return { ...item, k: newKey };
    });
    return { items, correctKey: newCorrect };
  };

  return pool.map(p => {
    if (p.opts) {
      const { items, correctKey } = shuffleAndRelabel(p.opts, p.a);
      return { ...p, opts: items, a: correctKey };
    }
    if (p.pistas) {
      const { items, correctKey } = shuffleAndRelabel(p.pistas, p.pista);
      return { ...p, pistas: items, pista: correctKey };
    }
    if (p.acciones) {
      const { items, correctKey } = shuffleAndRelabel(p.acciones, p.a);
      return { ...p, acciones: items, a: correctKey };
    }
    return p;
  });
};

