/* ═══════════════════════════════════════════════
   CONFETTI
═══════════════════════════════════════════════ */
const COLORS = ["#f7b731","#20bf6b","#3498db","#e84393","#fd9644","#a55eea","#fff"];
function Confetti() {
  const ps = Array.from({ length: 70 }, (_, i) => ({
    id:i, left:Math.random()*100, delay:Math.random()*2.4,
    dur:2.4+Math.random()*2, color:COLORS[i%COLORS.length],
    w:5+Math.random()*8, h:9+Math.random()*10, rot:Math.random()*360
  }));
  return <>{ps.map(p => (
    <div key={p.id} style={{
      position:"fixed", top:-20, left:`${p.left}%`, width:p.w, height:p.h,
      background:p.color, borderRadius:2, transform:`rotate(${p.rot}deg)`,
      animation:`confFall ${p.dur}s ${p.delay}s linear forwards`,
      zIndex:9999, pointerEvents:"none"
    }}/>
  ))}</>;
}

/* ═══════════════════════════════════════════════
   IMAGEN CON FALLBACK
═══════════════════════════════════════════════ */
function Hero({ src, alt, style, className }) {
  const [err, setErr] = useState(false);
  if (err) {
    return (
      <div className={className} style={{
        ...style, display:"flex", alignItems:"center", justifyContent:"center",
        background:"rgba(255,255,255,.04)", border:"1px dashed rgba(255,255,255,.16)",
        borderRadius:14, color:"rgba(255,255,255,.3)", fontSize:".7rem",
        fontFamily:"'Barlow Condensed',sans-serif", textAlign:"center", padding:8
      }}>{alt}</div>
    );
  }
  return <img src={src} alt={alt} style={style} className={className} onError={()=>setErr(true)}/>;
}

