/* ═══════════════════════════════════════════════
   PROGRESO DE RONDAS
═══════════════════════════════════════════════ */
function Progreso({ actual, resultados }) {
  return (
    <div style={{display:"flex",alignItems:"center",gap:4}}>
      {RONDAS.map((rd, i) => {
        const r = resultados[i];
        const on = i === actual - 1;
        const c = rd.heroe.color;
        const bg = r==="win" ? "#20bf6b" : r==="loss" ? "#e74c3c" : on ? `${c}33` : "rgba(255,255,255,.07)";
        const bd = on ? `2px solid ${c}` : r==="win" ? "2px solid #20bf6b" : r==="loss" ? "2px solid #e74c3c" : "2px solid transparent";
        const sh = on ? `0 0 12px ${c}` : r==="win" ? "0 0 8px rgba(32,191,107,.5)" : "none";
        return (
          <div key={rd.id} style={{display:"flex",alignItems:"center",gap:4}}>
            <div className="node" style={{background:bg,border:bd,boxShadow:sh}}>
              {r==="win" ? "⚡" : r==="loss" ? "💀" : `R${rd.id}`}
            </div>
            {i < RONDAS.length - 1 && <div style={{width:10,height:2,background:"rgba(255,255,255,.1)",borderRadius:1}}/>}
          </div>
        );
      })}
    </div>
  );
}

/* ═══════════════════════════════════════════════
   PANTALLA 1 — LOGIN SPLIT-SCREEN (sin scroll)
═══════════════════════════════════════════════ */
function BgmToggle() {
  const [on, setOn] = useState(!_bgmMuted);
  return (
    <button
      type="button"
      className={`bgm-btn${on ? "" : " off"}`}
      title={on ? "Silenciar música" : "Activar música"}
      onClick={() => {
        unlockAudio();
        SND.click();
        const playing = toggleBgm();
        setOn(playing);
        if (playing) startBgm();
      }}
    >{on ? "🎵" : "🔇"}</button>
  );
}

/* ═══════════════════════════════════════════════
   ACCESO — solo identificaciones en public/data/identificaciones.csv
═══════════════════════════════════════════════ */
const IDS_URL = "/data/identificaciones.csv";
let _idsPermitidos = null; // Set<string> | null
let _idsPromise = null;

const cargarIdsPermitidos = () => {
  if (_idsPermitidos) return Promise.resolve(_idsPermitidos);
  if (_idsPromise) return _idsPromise;
  _idsPromise = fetch(IDS_URL)
    .then((r) => {
      if (!r.ok) throw new Error("No se pudo cargar la lista de acceso");
      return r.text();
    })
    .then((text) => {
      const set = new Set();
      for (const line of text.split(/\r?\n/)) {
        const id = line.trim();
        if (/^\d{4,15}$/.test(id)) set.add(id);
      }
      _idsPermitidos = set;
      return set;
    })
    .catch((err) => {
      _idsPromise = null;
      throw err;
    });
  return _idsPromise;
};

function Bienvenida({ onEntrar }) {
  const [doc, setDoc] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const [listaOk, setListaOk] = useState(!!_idsPermitidos);
  const [listaErr, setListaErr] = useState("");

  useEffect(() => {
    let cancelled = false;
    cargarIdsPermitidos()
      .then(() => { if (!cancelled) { setListaOk(true); setListaErr(""); } })
      .catch(() => {
        if (!cancelled) {
          setListaOk(false);
          setListaErr("No se pudo cargar la lista de acceso. Recarga la página.");
        }
      });
    return () => { cancelled = true; };
  }, []);

  const go = async () => {
    const id = doc.trim();
    if (!id) return setErr("Ingresa tu número de documento");
    if (!/^\d{4,15}$/.test(id)) return setErr("Solo números, entre 4 y 15 dígitos");
    // CRÍTICO: desbloquear audio en el gesto del clic, ANTES del await
    unlockAudio();
    setLoading(true);
    setErr("");
    try {
      const v = await validarDocumento(id, {
        checkLocal: async (docId) => {
          const set = await cargarIdsPermitidos();
          return set.has(docId);
        },
      });
      if (!v.ok) {
        setErr(v.error || "Esta identificación no está autorizada para jugar.");
        setLoading(false);
        return;
      }
      SND.thunder();
      startBgm();
      onEntrar(id, v.sesion && canResumeSession(v.sesion) ? v.sesion : null);
    } catch (_) {
      setErr("No se pudo validar el acceso. Intenta de nuevo.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="split">
      {/* IZQUIERDA — imagen 4:5 */}
      <div className="split-img">
        <LoginArt style={{
          width:"100%", height:"100%", objectFit:"contain", objectPosition:"center bottom", display:"block"
        }}/>
      </div>

      {/* DERECHA — formulario */}
      <div className="split-form">
        <div className="split-inner">
          <h1 className="title-one">
            <span className="t-c">CIBER</span>{" "}
            <span className="t-g">HÉROES</span>{" "}
            <span className="t-d">DOOMSDAY</span>
          </h1>

          <div className="title-rule"/>

          <p className="split-sub">
            Clasificación de Activos de Información
          </p>

          <p className="split-body">
            <strong className="gold-t">Doctor Doom</strong> infiltró los sistemas de la institución
            y quiere filtrar la información. <strong className="gold-t">Trueno</strong> y su equipo
            te necesitan: clasifica cada activo en su nivel correcto y detén al villano.
          </p>

          {/* Chips de niveles */}
          <div className="split-chips">
            {KEYS.map(k => {
              const n = NIVELES[k];
              return (
                <span key={k} className="chip" style={{background:n.bg,borderColor:n.bd,color:n.color}}>
                  {k}
                </span>
              );
            })}
          </div>

          <div className="split-field">
            <div className="lbl mb4">Tu identificación</div>
            <input className="input" placeholder="Número de documento…" value={doc} maxLength={15}
              disabled={loading || !!listaErr}
              onChange={e => { setDoc(e.target.value.replace(/\D/g, "")); setErr(""); }}
              onKeyDown={e => e.key === "Enter" && !loading && go()}/>
            {err && <p className="err">{err}</p>}
            {listaErr && <p className="err">{listaErr}</p>}
            {!listaOk && !listaErr && (
              <p style={{fontSize:".75rem",color:"rgba(255,255,255,.4)",marginTop:6}}>
                Cargando lista de acceso…
              </p>
            )}
          </div>

          <button
            className="btn btn-gold"
            onPointerDown={unlockAudio}
            onClick={go}
            disabled={loading || !!listaErr || !listaOk}
          >
            {loading ? "Validando…" : "⚡ ¡UNIRME AL EQUIPO!"}
          </button>

          <div className="split-org">Fundación Cardiovascular de Colombia · Ciberseguridad</div>
          <p className="split-foot">🔒 Acceso solo con identificación autorizada · Ciber Héroes FCV</p>
        </div>
      </div>
    </div>
  );
}

