/* ═══════════════════════════════════════════════
   PANTALLA — INTRO DE HÉROES (split + tecleo sync)
═══════════════════════════════════════════════ */
function Intro({ onTerminar, onVolver, documento }) {
  const [n, setN] = useState(0);
  const [autoNext, setAutoNext] = useState(true);
  const [typed, setTyped] = useState("");
  const [typing, setTyping] = useState(false);
  const [waitingNarr, setWaitingNarr] = useState(false);
  const h = HEROES[n];
  const ultimo = n === HEROES.length - 1;
  const skipRef = useRef(false);
  const autoNextRef = useRef(autoNext);
  const onTerminarRef = useRef(onTerminar);
  const typedFullRef = useRef("");
  const rafRef = useRef(0);
  const typeTimerRef = useRef(0);
  const runIdRef = useRef(0);
  const keysReadyRef = useRef(0); // ignora teclas residuales del login (Enter)
  autoNextRef.current = autoNext;
  onTerminarRef.current = onTerminar;

  useEffect(() => {
    // Evita que el Enter de "Unirme" dispare avanzar al montar la intro
    keysReadyRef.current = Date.now() + 600;
  }, []);

  const stopTypeSync = () => {
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = 0;
    }
    if (typeTimerRef.current) {
      clearInterval(typeTimerRef.current);
      typeTimerRef.current = 0;
    }
  };

  const revealAll = () => {
    stopTypeSync();
    setTyped(typedFullRef.current || HEROES[n]?.texto || "");
    setTyping(false);
    setWaitingNarr(false);
  };

  const syncTypewriter = (audio, fullText) => {
    stopTypeSync();
    typedFullRef.current = fullText || "";
    setTyping(true);
    setWaitingNarr(false);
    const a = audio || null;
    const full = typedFullRef.current;
    if (!full) return;

    const estimateMs = Math.max(2200, full.length * 28);
    const getDurationMs = () =>
      (a && Number.isFinite(a.duration) && a.duration > 0 ? a.duration * 1000 : estimateMs);

    const startedAt = performance.now();
    const renderByProgress = () => {
      const total = getDurationMs();
      const elapsed = performance.now() - startedAt;
      const t = Math.max(0, Math.min(1, elapsed / total));
      const chars = Math.max(1, Math.min(full.length, Math.floor(t * full.length)));
      setTyped(full.slice(0, chars));
      if (chars >= full.length) setTyping(false);
    };

    // Fallback robusto: asegura escritura progresiva aunque currentTime/duration no avancen bien.
    typeTimerRef.current = setInterval(() => {
      renderByProgress();
      const total = getDurationMs();
      const elapsed = performance.now() - startedAt;
      if ((a && a.ended) || elapsed >= total) {
        setTyped(full);
        setTyping(false);
        stopTypeSync();
      }
    }, 45);

    // Refuerzo por frame para suavidad cuando el navegador sí reporta tiempos del audio.
    const tick = () => {
      if (a && a.ended) return;
      renderByProgress();
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  };

  const avanzar = useCallback(() => {
    if (Date.now() < keysReadyRef.current) return;
    SND.click();
    skipRef.current = true;
    stopTypeSync();
    stopVoz();
    if (n >= HEROES.length - 1) { SND.thunder(); onTerminarRef.current(); }
    else setN(v => v + 1);
  }, [n]);

  const retroceder = useCallback(() => {
    if (Date.now() < keysReadyRef.current) return;
    if (n > 0) {
      SND.click();
      skipRef.current = true;
      stopTypeSync();
      stopVoz();
      setN(v => v - 1);
    } else if (onVolver) {
      SND.click();
      skipRef.current = true;
      stopTypeSync();
      stopVoz();
      onVolver();
    }
  }, [n, onVolver]);

  const saltar = () => {
    SND.click();
    skipRef.current = true;
    stopTypeSync();
    stopVoz();
    onTerminarRef.current();
  };

  useEffect(() => {
    skipRef.current = false;
    const runId = ++runIdRef.current;
    let cancelled = false;
    const step = n;
    const hero = HEROES[step];
    const vozId = hero?.voz;
    const fullText = hero?.texto || "";

    setTyped("");
    setTyping(false);
    typedFullRef.current = fullText;
    setWaitingNarr(false);

    const stillHere = () =>
      !cancelled && !skipRef.current && runIdRef.current === runId;

    (async () => {
      // Strict Mode: deja morir el mount fantasma
      await new Promise(r => setTimeout(r, 120));
      if (!stillHere()) return;

      unlockAudio();

      let gotAudio = false;
      let startedFallback = false;
      if (vozId) {
        // Si el audio no dispara onAudio (caso típico móvil), arrancar tecleo por fallback.
        const fallbackTimer = setTimeout(() => {
          if (!stillHere() || startedFallback || gotAudio) return;
          startedFallback = true;
          syncTypewriter(null, fullText);
        }, 420);
        await playVoz(vozId, {
          onAudio: (audio) => {
            if (!stillHere()) return;
            clearTimeout(fallbackTimer);
            gotAudio = true;
            syncTypewriter(audio, fullText);
          },
        });
        clearTimeout(fallbackTimer);
        if (!stillHere()) return;
        setTyped(fullText);
        setTyping(false);
      } else {
        syncTypewriter(null, fullText);
        gotAudio = true;
      }

      // Si la voz no llegó a sonar, quédate en este personaje (no saltar a Trueno)
      if (!gotAudio) {
        setTyped(fullText);
        setWaitingNarr(false);
        return;
      }

      if (!autoNextRef.current) return;
      if (!stillHere()) return;

      // Tras la regla de oro, pausa larga para poder leerla; si no hay tip, pausa breve
      const tipHold = hero?.regla ? 3200 : 700;
      await new Promise(r => setTimeout(r, tipHold));
      if (!stillHere()) return;

      if (step >= HEROES.length - 1) onTerminarRef.current();
      else setN(v => (v === step ? v + 1 : v));
    })();

    return () => {
      cancelled = true;
      stopTypeSync();
      stopVoz();
    };
  }, [n]);

  useEffect(() => {
    const k = e => {
      if (Date.now() < keysReadyRef.current) return;
      // No usar Enter: es el mismo que envía el login y saltaba a Trueno
      if (e.key === "ArrowRight") avanzar();
      if (e.key === "ArrowLeft") retroceder();
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [avanzar, retroceder]);

  const showTip = h.regla && typed.length >= (h.texto?.length || 0);

  return (
    <div className="intro-stage" style={{
      "--intro-glow": `${h.color}66`,
      "--intro-glow-strong": `${h.color}aa`,
    }}>
      <div className="intro-stage-ui">
        <div>
          <div className="intro-top">
            <div className="lbl">Conoce al equipo · {n + 1} de {HEROES.length}</div>
            <div style={{display:"flex",gap:8,alignItems:"center"}}>
              <button className="intro-skip" type="button"
                onClick={() => setAutoNext(v => !v)}
                title="Auto-avanzar al terminar la voz">
                {autoNext ? "Auto ✓" : "Auto off"}
              </button>
              <button className="intro-skip" type="button" onClick={saltar}>
                Saltar intro →
              </button>
            </div>
          </div>
          <div className="intro-bar">
            {HEROES.map((x, idx) => (
              <div key={x.id} style={{
                flex:1, height:5, borderRadius:3, transition:"all .35s",
                background: idx <= n ? (x.color || "#f7b731") : "rgba(255,255,255,.1)",
                boxShadow: idx === n ? `0 0 10px ${x.color}` : "none"
              }}/>
            ))}
          </div>
        </div>

        <div className="intro-split" key={h.id}>
          <div className="intro-copy">
            <div className="intro-glass" onClick={revealAll} title="Clic para mostrar todo el texto">
              {h.nivel && (
                <div className="intro-chip" style={{borderColor:`${h.color}99`,color:h.color}}>
                  NIVEL {h.nivel} · {NIVELES[h.nivel].nombre}
                </div>
              )}
              <div className="intro-nombre" style={{color:h.color}}>{h.nombre}</div>
              <div className="intro-rol">{h.rol} · {h.poder}</div>
              <p className="intro-quote">"{h.frase}"</p>
              <div className="intro-type" aria-live="polite">
                {waitingNarr ? (
                  <span className="intro-wait">Escucha el briefing…</span>
                ) : (
                  <>
                    {typed}
                    {typing && <span className="caret" aria-hidden />}
                  </>
                )}
              </div>
              {showTip && (
                <div className="intro-tip">Regla de oro: {h.regla}</div>
              )}
            </div>
          </div>

          <div className="intro-art">
            <Hero src={heroSrc(h.img)} alt={h.nombre} />
          </div>
        </div>

        <div className="intro-nav">
          <button className="intro-prev" type="button"
            onClick={retroceder}
            disabled={n === 0 && !onVolver}>
            {n === 0 ? "← Volver" : "← Anterior"}
          </button>
          <div className="intro-dots">
            {HEROES.map((x, idx) => (
              <span key={x.id} onClick={() => {
                if (idx === n) return;
                if (Date.now() < keysReadyRef.current) return;
                SND.click();
                skipRef.current = true;
                stopTypeSync();
                stopVoz();
                setN(idx);
              }}
                style={{
                  width: idx === n ? 22 : 9, height:9, borderRadius:5, cursor:"pointer",
                  background: idx === n ? x.color : "rgba(255,255,255,.18)",
                  transition:"all .3s", display:"inline-block"
                }}/>
            ))}
          </div>
          <button className="btn btn-gold intro-next" type="button"
            onClick={avanzar}>
            {ultimo ? "⚡ ¡A LA BATALLA!" : "Siguiente →"}
          </button>
        </div>
      </div>
    </div>
  );
}

function Instrucciones({ onIniciar, onVolver, documento }) {
  const reglas = [
    { i:"📋", t:<><strong className="gold-t">3 retos por ronda</strong>. Clasifica niveles (N1–N4) o detecta el error en una historia.</> },
    { i:"⚡", t:<>Acierto = <strong className="green-t">Mjolnir golpea a Doom</strong> y su poder se reduce.</> },
    { i:"💀", t:<>Error = <strong className="red-t">Doctor Doom ataca</strong> y pierdes un rayo de Mjolnir.</> },
    { i:"🛡", t:<>Tienes <strong className="gold-t">3 rayos en total</strong> para todo el juego (no se reinician por ronda). Cada error consume un rayo; si se agotan, la partida termina.</> },
    { i:"🎯", t:<>Completa las <strong className="gold-t">3 preguntas de cada ronda</strong> mientras te queden rayos para avanzar a la siguiente.</> },
    { i:"🌩", t:<>Son <strong className="gold-t">4 rondas</strong> con mecánicas distintas: clasifica, detecta, investiga y decide.</> },
  ];

  useEffect(() => {
    let cancelled = false;
    (async () => {
      await new Promise(r => setTimeout(r, 120));
      if (cancelled) return;
      unlockAudio();
      await playVoz("briefing_titulo");
    })();
    return () => { cancelled = true; stopVoz(); };
  }, []);

  return (
    <div className="screen">
    <div className="card card-flex">
      <div className="row ic" style={{marginBottom:0,flexShrink:0}}>
        <div className="f1">
          <div className="lbl mb8">Briefing de misión</div>
          <div className="h1">Prepárate<br/>para la batalla</div>
          <div className="tag mt8">Agente: <span className="gold-t">{documento}</span></div>
        </div>
        <Hero src={heroSrc("thorIdle")} alt="Trueno" className="instr-hero" style={{
          borderRadius:14, display:"block", flexShrink:0,
          filter:"drop-shadow(0 10px 30px rgba(247,183,49,.3))"
        }}/>
      </div>

      <div className="div" style={{flexShrink:0}}/>

      <div className="row instr-row" style={{gap:"clamp(12px,2vw,26px)"}}>
        <div className="instr-col" style={{flex:"0 0 clamp(200px,22vw,280px)",overflow:"auto"}}>
          <div className="lbl mb8" style={{flexShrink:0}}>🗂️ Niveles de información</div>
          {KEYS.map(k => {
            const n = NIVELES[k];
            return (
              <div key={k} className="niv-item" style={{background:n.bg,border:`1px solid ${n.bd}`,flexShrink:0}}>
                <div className="niv-t" style={{color:n.color}}>{k} · {n.nombre}</div>
                <div className="niv-d">{n.desc}</div>
              </div>
            );
          })}
        </div>
        <div className="f1 instr-col">
          <div className="lbl mb8" style={{flexShrink:0}}>⚡ Cómo se juega</div>
          <div className="instr-rules">
            {reglas.map((r,i) => (
              <div key={i} className="rule-item" style={{borderRadius:"0 9px 9px 0",flexShrink:0}}>
                <span>{r.i}</span><p>{r.t}</p>
              </div>
            ))}
          </div>
          <div className="instr-enemy">
            <Hero src={IMG.doom} alt="Doom"/>
            <div style={{minWidth:0}}>
              <div style={{fontFamily:"'Anton',sans-serif",fontSize:"clamp(.85rem,1.8vh,1rem)",color:"#00cc00",letterSpacing:".08em"}}>TU ENEMIGO</div>
              <div style={{fontSize:"clamp(.72rem,1.5vh,.85rem)",color:"rgba(0,204,0,.75)",fontFamily:"'Barlow Condensed',sans-serif",fontWeight:600,lineHeight:1.35}}>
                Doctor Doom · Destructor de la FCV
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="flex ic jb fw" style={{gap:10,flexShrink:0,marginTop:4}}>
        {onVolver && (
          <button className="intro-skip" type="button" style={{padding:"clamp(10px,1.6vh,14px) clamp(14px,1.5vw,20px)"}}
            onClick={() => { stopVoz(); SND.click(); onVolver(); }}>
            ← Volver
          </button>
        )}
        <button className="btn btn-gold" style={{flex:1,minWidth:0}} onClick={() => { stopVoz(); SND.thunder(); onIniciar(); }}>
          ⚡ ¡COMENZAR MISIÓN!
        </button>
      </div>
    </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   OVERLAY — DOOM ATACA (pantalla completa)
═══════════════════════════════════════════════ */
function DoomAtaca({ ronda, motivo, onCerrar }) {
  const onCerrarRef = useRef(onCerrar);
  onCerrarRef.current = onCerrar;
  useEffect(() => { SND.doom(); }, []);
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        SND.click();
        onCerrarRef.current?.();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const cerrar = () => { SND.click(); onCerrarRef.current?.(); };

  return (
    <div className="ov" style={{background:"rgba(0,6,0,.94)"}} onClick={cerrar}>
      <div style={{position:"absolute",inset:0,background:"repeating-linear-gradient(0deg,rgba(0,255,0,.035) 0,rgba(0,255,0,.035) 1px,transparent 1px,transparent 4px)",pointerEvents:"none"}}/>
      <div style={{position:"absolute",inset:0,animation:"flashGreen .6s ease-out",pointerEvents:"none"}}/>

      <div className="ov-inner" onClick={e => e.stopPropagation()}>
        <Hero src={IMG.doom} alt="Doctor Doom ataca" style={{
          width:"auto", maxWidth:"min(42vw,200px)", maxHeight:"min(26vh,180px)",
          borderRadius:16, display:"block", margin:"0 auto", objectFit:"contain",
          animation:"zoomHit .5s cubic-bezier(.17,.89,.32,1.28)",
          filter:"drop-shadow(0 0 42px rgba(0,220,0,.6))", flexShrink:1
        }}/>

        <div style={{fontFamily:"'Anton',sans-serif",fontSize:"clamp(1.25rem,4.6vh,2.4rem)",color:"#00cc00",letterSpacing:".07em",textShadow:"0 0 28px #00ff00",animation:"glitch .32s steps(2) infinite",flexShrink:0}}>
          ¡DOCTOR DOOM ATACA!
        </div>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:"clamp(.78rem,1.7vh,.95rem)",color:"rgba(0,255,0,.7)",letterSpacing:".12em",flexShrink:0}}>
          {ronda.poder} · Trueno pierde un rayo de Mjolnir
        </div>

        {motivo && (
          <div className="ov-why">
            <div className="ov-why-lbl">Por esto estaba mal</div>
            <div className="ov-why-txt">{motivo}</div>
          </div>
        )}

        <button type="button" onClick={cerrar} style={{
          padding:"12px 32px", background:"linear-gradient(135deg,#003300,#006600)",
          border:"2px solid #00cc00", borderRadius:12, color:"#00ff00",
          fontFamily:"'Anton',sans-serif", fontSize:"clamp(.95rem,2.2vh,1.05rem)", letterSpacing:".07em",
          cursor:"pointer", animation:"pulseGreen 1.1s ease-in-out infinite",
          flexShrink:0, marginTop:4
        }}>⚡ ¡CONTINUAR BATALLA!</button>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   OVERLAY — EL EQUIPO ATACA (respuesta correcta)
═══════════════════════════════════════════════ */
function EquipoAtaca({ nivel, heroe, motivo, onCerrar }) {
  const onCerrarRef = useRef(onCerrar);
  onCerrarRef.current = onCerrar;
  useEffect(() => {
    const t = setTimeout(() => onCerrarRef.current?.(), 2800);
    return () => clearTimeout(t);
  }, []);

  const color = heroe?.color || "#f7b731";
  const src = IMG[heroe?.imgOk || heroe?.img] || IMG.thorGana;

  return (
    <div className="ov" style={{background:"rgba(6,4,0,.92)"}} onClick={onCerrar}>
      <div style={{position:"absolute",inset:0,animation:"flashGold .6s ease-out",pointerEvents:"none"}}/>

      <div className="ov-inner" style={{padding:20}}>
        <Hero src={src} alt={`${heroe?.nombre || "Héroe"} victoria`} style={{
          width:"min(100%,420px)", maxHeight:"48vh", objectFit:"contain",
          borderRadius:16, display:"block", margin:"0 auto 14px",
          animation:"zoomHit .5s cubic-bezier(.17,.89,.32,1.28)",
          filter:`drop-shadow(0 0 42px ${color}99)`,
        }}/>

        <div style={{
          fontFamily:"'Anton',sans-serif", fontSize:"clamp(1.5rem,5.5vw,2.6rem)",
          letterSpacing:".07em", color, textShadow:`0 0 28px ${color}`
        }}>
          ¡BUENA JUGADA!
        </div>

        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:"1.05rem",color:"rgba(247,183,49,.9)",marginTop:6,letterSpacing:".08em"}}>
          {heroe?.nombre || "HÉROE"} · RESPUESTA CORRECTA
        </div>

        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:600,fontSize:".95rem",color:"rgba(255,255,255,.7)",marginTop:4,letterSpacing:".06em"}}>
          {nivel}
        </div>

        {motivo && (
          <div className="ov-why" style={{borderColor:`${color}55`,background:"rgba(255,255,255,.06)"}}>
            <div className="ov-why-lbl" style={{color}}>Por qué fue correcta</div>
            <div className="ov-why-txt">{motivo}</div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   MODAL — FIN DE RONDA
═══════════════════════════════════════════════ */
function ModalRonda({ resultado, ronda, siguiente, aciertos, vidasRestantes, onSeguir, esFinal }) {
  useEffect(() => { resultado === "win" ? SND.win() : SND.doom(); }, []);
  const gano = resultado === "win";
  return (
    <div className="ov">
      {gano && <Confetti/>}
      <div className="box">
        <Hero src={gano ? IMG[ronda.heroe.imgOk] : IMG.doomGana} alt={gano ? `${ronda.heroe.nombre} victoria` : "Doom conquista"} style={{
          width:"100%", maxWidth:280, borderRadius:14, display:"block", margin:"0 auto 14px",
          filter: gano ? "drop-shadow(0 0 26px rgba(247,183,49,.5))" : "drop-shadow(0 0 26px rgba(0,204,0,.4))"
        }}/>

        <div style={{
          fontFamily:"'Anton',sans-serif", fontSize:"clamp(1.6rem,5vw,2.3rem)", letterSpacing:".05em",
          background: gano ? "linear-gradient(135deg,#f7b731,#20bf6b)" : "linear-gradient(135deg,#00cc00,#e74c3c)",
          WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent", backgroundClip:"text"
        }}>
          {gano ? (esFinal ? "¡DOOM DERROTADO!" : "¡RONDA SUPERADA!") : "¡SIN RAYOS!"}
        </div>

        <div style={{fontFamily:"'Anton',sans-serif",fontSize:"1.7rem",color:"#fff",margin:"6px 0"}}>
          {aciertos}/3 aciertos · {vidasRestantes} rayo{vidasRestantes === 1 ? "" : "s"} restante{vidasRestantes === 1 ? "" : "s"}
        </div>

        <p style={{fontSize:".9rem",color:"rgba(255,255,255,.6)",marginBottom:20,lineHeight:1.6}}>
          {gano
            ? (esFinal
                ? "¡Trueno derrotó a Doctor Doom! La información de la FCV está protegida. Eres el Guardián Supremo."
                : `¡${ronda.heroe.nombre} completó la ronda! Te quedan ${vidasRestantes} rayo${vidasRestantes === 1 ? "" : "s"} para el resto del juego. ${siguiente ? siguiente.heroe.nombre : "El equipo"} toma el relevo.`)
            : "Se agotaron los 3 rayos de Mjolnir. Tu participación en el juego ha terminado."}
        </p>

        <button className="btn btn-gold" onClick={() => { SND.click(); onSeguir(); }}>
          {esFinal ? "🎊 Ver resultado final" : gano ? "⚡ Siguiente ronda →" : "Ver resultados"}
        </button>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   PANTALLA 3 — JUEGO
═══════════════════════════════════════════════ */
function Juego({ rondaIdx, resultados, onFinRonda, puntajeTotal, vidasRestantes, onVidasChange }) {
  const ronda      = RONDAS[rondaIdx];
  const preguntas  = useRef(preguntasRonda(ronda.id)).current;
  const [i,        setI]        = useState(0);
  const [elegida,  setElegida]  = useState(null);
  const [feedback, setFeedback] = useState(null);
  const [aciertos, setAciertos] = useState(0);
  const [respuestasOk, setRespuestasOk] = useState(() => Array(preguntas.length).fill(null));
  const vidasRef = useRef(vidasRestantes);
  vidasRef.current = vidasRestantes;
  const [estado,   setEstado]   = useState("idle");     // idle | ok | fail
  const [hpDoom,   setHpDoom]   = useState(3);
  const [verDoom,  setVerDoom]  = useState(false);
  const [verEquipo,setVerEquipo]= useState(null);
  const [pista,    setPista]    = useState(false);
  const [fin,      setFin]      = useState(null);
  const [dragOver, setDragOver] = useState(null);
  const [dragging, setDragging] = useState(false);
  const [invInfo,  setInvInfo]  = useState(null);
  const [decCons,  setDecCons]  = useState(null);
  const timersRef = useRef([]);
  const lockedRef = useRef(false);
  const aciertosRef = useRef(0);
  const doomPendienteRef = useRef(null); // "next" | "loss" | null
  const iRef = useRef(0);
  iRef.current = i;

  const p = preguntas[i];
  const tareaModo = ({
    bandejas: "Elige el nivel N1–N4 donde debe guardarse este activo",
    error: "Detecta el error crítico en la historia (no lo correcto ni lo irrelevante)",
    investiga: "Elige la pregunta útil: esa pista revela el nivel correcto",
    decision: "Elige la acción que mejor protege la información",
    quiz: "Elige el nivel correcto para este activo",
  })[ronda.modo] || "Elige la respuesta correcta";

  const clearTimers = () => {
    timersRef.current.forEach(clearTimeout);
    timersRef.current = [];
  };
  const later = (fn, ms) => {
    const t = setTimeout(fn, ms);
    timersRef.current.push(t);
    return t;
  };

  const marcarRespuesta = (ok) => {
    const idx = iRef.current;
    setRespuestasOk(prev => {
      const next = [...prev];
      next[idx] = ok;
      return next;
    });
  };

  useEffect(() => {
    clearTimers();
    lockedRef.current = false;
    setInvInfo(null);
    setDecCons(null);
    setElegida(null);
    setFeedback(null);
    setPista(false);
    setEstado("idle");
    setDragOver(null);
    setDragging(false);
    return () => clearTimers();
  }, [i]);

  const irSiguientePregunta = () => {
    lockedRef.current = false;
    setI(prev => {
      const sig = prev + 1;
      if (sig >= preguntas.length) {
        // Completaste la ronda: avanzas si aún te quedan rayos globales
        setFin({ r: vidasRef.current > 0 ? "win" : "loss" });
        return prev;
      }
      return sig;
    });
  };

  const avanzarPregunta = () => {
    later(() => irSiguientePregunta(), 5200);
  };

  const cerrarDoom = () => {
    setVerDoom(false);
    const pend = doomPendienteRef.current;
    doomPendienteRef.current = null;
    if (pend === "loss") setFin({ r: "loss" });
    else if (pend === "next") irSiguientePregunta();
  };

  const aplicarAcierto = (msg, nivelEq) => {
    SND.correct(); SND.thunder();
    lockedRef.current = true;
    setEstado("ok");
    marcarRespuesta(true);
    aciertosRef.current += 1;
    setAciertos(aciertosRef.current);
    setHpDoom(h => Math.max(0, h - 1));
    setFeedback({ ok:true, msg });
    later(() => setVerEquipo({ nivel: nivelEq, motivo: msg }), 2800);
  };

  const aplicarFallo = (msg) => {
    SND.wrong();
    lockedRef.current = true;
    setEstado("fail");
    marcarRespuesta(false);
    const nv = vidasRef.current - 1;
    onVidasChange(nv);
    setFeedback({ ok:false, msg });
    doomPendienteRef.current = nv <= 0 ? "loss" : "next";
    later(() => setVerDoom(true), 1800);
    return nv > 0;
  };

  const responder = (k) => {
    if (elegida || lockedRef.current) return;
    setElegida(k);
    const modo = ronda.modo;

    // R3 Investiga: una sola elección (la pregunta útil).
    // La pista ya revela el nivel — no volver a mostrar las bandejas N1–N4.
    if (modo === "investiga") {
      const ok = k === p.pista;
      const elegidaPista = (p.pistas || []).find(x => x.k === k);
      if (ok) {
        const nivelEq = `${p.nivel} · ${NIVELES[p.nivel].nombre}`;
        setInvInfo(elegidaPista?.revela || `Nivel revelado: ${p.nivel}`);
        setFeedback({ ok:true, msg:`Pista correcta → ${nivelEq}` });
        lockedRef.current = true;
        later(() => {
          aplicarAcierto(`Clasificación: ${nivelEq}`, nivelEq);
          avanzarPregunta(true);
        }, 1100);
      } else {
        const buena = (p.pistas || []).find(x => x.k === p.pista);
        aplicarFallo(buena ? `Debías investigar: ${buena.t}` : "Esa no era la pista útil.");
      }
      return;
    }

    let correctKey = p.a;
    const ok = k === correctKey;

    let msgOk, msgNo, nivelEq;
    if (modo === "error") {
      msgOk = p.explica || "Correcto: ese era el error crítico.";
      const correcta = (p.opts || []).find(o => o.k === p.a);
      msgNo = p.explica || (correcta ? `El error crítico era: ${correcta.t}` : "Ese no era el error crítico.");
      nivelEq = "Error detectado";
    } else if (modo === "decision") {
      const act = (p.acciones || []).find(o => o.k === k);
      const buena = (p.acciones || []).find(o => o.k === p.a);
      setDecCons({ ok, text: act?.cons || "" });
      msgOk = act?.cons || "Buena decisión.";
      msgNo = buena ? `Mejor era: ${buena.t}. ${buena.cons || ""}` : "Mala decisión.";
      nivelEq = "Decisión heroica";
    } else {
      msgOk = `Es ${p.a} · ${NIVELES[p.a].nombre}. ${p.tip || ""}`;
      msgNo = `La respuesta correcta era ${p.a} · ${NIVELES[p.a].nombre}. ${p.tip || ""}`;
      nivelEq = `${p.a} · ${NIVELES[p.a].nombre}`;
    }

    if (ok) {
      aplicarAcierto(msgOk, nivelEq);
      avanzarPregunta();
    } else {
      aplicarFallo(msgNo);
    }
  };

  // Héroe campeón de esta ronda.
  // reaccionan con efectos CSS sobre su pose base.
  const hero = ronda.heroe;
  const imgHero =
    estado === "ok"   ? IMG[hero.imgOk   || hero.img] :
    estado === "fail" ? IMG[hero.imgFail || hero.img] : IMG[hero.img];
  const claseHero = estado === "ok" ? "hero-ok" : estado === "fail" ? "hero-fail" : "hero-idle";
  const esFinal = rondaIdx === RONDAS.length - 1;

  return (
    <>
      {verDoom && <DoomAtaca ronda={ronda} motivo={feedback?.msg} onCerrar={cerrarDoom}/>}
      {verEquipo && <EquipoAtaca nivel={verEquipo.nivel} motivo={verEquipo.motivo} heroe={ronda.heroe} onCerrar={() => setVerEquipo(null)}/>}
      {fin && (
        <ModalRonda resultado={fin.r} ronda={ronda} siguiente={RONDAS[rondaIdx + 1]} aciertos={aciertos}
          vidasRestantes={vidasRestantes}
          esFinal={esFinal && fin.r === "win"}
          onSeguir={() => onFinRonda(fin.r, {
            aciertos,
            preguntasRonda: respuestasOk.filter(v => v !== null).length,
            vidasRestantes,
          })}/>
      )}

      <div className="game-shell">
      <div className="card card-full">
        {/* TOP */}
        <div className="flex ic jb fw game-top" style={{gap:10}}>
          <div>
            <div className="lbl mb4">{ronda.nombre}</div>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,letterSpacing:".1em",
              fontSize:"clamp(.75rem,1.6vh,.95rem)",color:ronda.heroe.color,marginBottom:6,textTransform:"uppercase"}}>
              {({bandejas:"Bandejas",error:"Detecta el error",investiga:"Investiga",decision:"Decisión",quiz:"Cuestionario"})[ronda.modo] || ronda.modo}
            </div>
            <Progreso actual={rondaIdx + 1} resultados={resultados}/>
          </div>
          <div className="flex ic fw" style={{gap:8}}>
            <div className="badge b-gold">⚡ {puntajeTotal + aciertos} aciertos</div>
            <div className="lives">
              {[0,1,2].map(n => <span key={n} className={`life ${n >= vidasRestantes ? "off" : ""}`}>⚡</span>)}
            </div>
          </div>
        </div>
        <div className="div game-div"/>

        <div className="row">
          {/* IZQUIERDA — Héroe */}
          <div className="col lado lado-hero">
            <div className="lbl center" style={{color:hero.color}}>⚡ {hero.nombre}</div>
            <Hero src={imgHero} alt={hero.nombre} className={`fit-img ${claseHero}`} style={{
              borderRadius:14, display:"block", transition:"filter .3s"
            }}/>
            <div className="lado-txt" style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:"clamp(.85rem,1.9vh,1.12rem)",color:"rgba(255,255,255,.58)",letterSpacing:".09em",textAlign:"center",fontWeight:700}}>
              {hero.rol.toUpperCase()}
            </div>
            <div className="hero-grito" style={{borderColor:`${hero.color}55`}}>
              "{hero.grito}"
            </div>

            {/* Progreso preguntas */}
            <div style={{width:"100%",flexShrink:0}}>
              <div className="lbl mb8 center">Progreso de ronda</div>
              <div style={{display:"flex",gap:6}}>
                {preguntas.map((_, n) => (
                  <div key={n} style={{
                    flex:1, height:"clamp(6px,1.1vh,10px)", borderRadius:5, transition:"all .3s",
                    background: respuestasOk[n] === true ? "#20bf6b"
                      : respuestasOk[n] === false ? "#e74c3c"
                      : n === i ? "rgba(247,183,49,.6)" : "rgba(255,255,255,.1)",
                    boxShadow: n === i ? "0 0 10px rgba(247,183,49,.5)" : "none"
                  }}/>
                ))}
              </div>
            </div>
          </div>

          {/* CENTRO — Pregunta */}
          <div className="col f1 center-col">
            <div className="flex ic jb fw" style={{gap:8}}>
              <div className="lbl" style={{color:"rgba(247,183,49,.78)",fontSize:"clamp(13px,2vh,18px)"}}>
                🎯 {ronda.modo === "bandejas" ? "Activo" : "Caso"} {i + 1} de {preguntas.length}
              </div>
              <button onClick={() => { SND.click(); setPista(v => !v); }} style={{
                background:"rgba(247,183,49,.12)", border:"1px solid rgba(247,183,49,.35)",
                borderRadius:10, padding:"clamp(8px,1.4vh,13px) clamp(14px,1.6vw,20px)", color:"#f7b731", fontSize:"clamp(.95rem,2.05vh,1.22rem)",
                cursor:"pointer", fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700,
                letterSpacing:".04em",
                visibility: (ronda.modo === "investiga" || ronda.modo === "decision") ? "hidden" : "visible",
              }}>{pista ? "▲ Ocultar pista" : "💡 Ver pista"}</button>
            </div>

            {ronda.modo === "bandejas" && (
            <div className="qbox">
              <div className="lbl mb8" style={{color:"rgba(247,183,49,.65)",fontSize:"clamp(11px,1.6vh,15px)"}}>
                DOCUMENTO PARA EL ESCUDO
              </div>
              <div className="qtext">"{p.q}"</div>
            </div>
            )}

            {pista && (ronda.modo === "bandejas" || ronda.modo === "quiz") && (
              <div className="hint">💡 {p.tip}</div>
            )}

            {(ronda.modo === "bandejas" || ronda.modo === "quiz") && (
              <div className="task-line">{tareaModo}</div>
            )}

            {/* Opciones según modo de ronda */}
            {ronda.modo === "bandejas" ? (
              <div className="play-panel">
                <div className="modo-badge" style={{borderColor:"rgba(243,156,18,.55)",color:"#f39c12",background:"rgba(243,156,18,.12)"}}>
                  Modo · Bandejas del escudo
                </div>
                <div className="bandejas-hint">🛡 Toca la bandeja del escudo donde debe guardarse este activo</div>
                <div className="bandejas">
                  {KEYS.map(k => {
                    const n = NIVELES[k];
                    const rev = !!elegida;
                    const esCorrecta = k === p.a;
                    const elegidaEsta = elegida === k;
                    const icono = { N1:"🧬", N2:"📜", N3:"⚙️", N4:"📢" }[k];
                    const bg = rev
                      ? (esCorrecta ? "rgba(32,191,107,.28)" : elegidaEsta ? "rgba(231,76,60,.22)" : "rgba(0,0,0,.2)")
                      : n.bg;
                    const bd = rev
                      ? (esCorrecta ? "#20bf6b" : elegidaEsta ? "#e74c3c" : "rgba(255,255,255,.1)")
                      : n.bd;
                    return (
                      <button key={k} type="button" className="bandeja" disabled={rev}
                        onClick={() => responder(k)}
                        style={{
                          background:bg, borderColor:bd, color:n.color,
                          opacity: rev && !esCorrecta && !elegidaEsta ? .35 : 1,
                          boxShadow: rev && esCorrecta ? `0 0 28px ${n.color}88` : `0 8px 24px ${n.color}22`,
                        }}>
                        <span className="bandeja-icon">{icono}</span>
                        <span className="bandeja-text">
                          <span className="bandeja-k">{k}</span>
                          <span className="bandeja-n">{n.nombre}</span>
                        </span>
                        <span className="bandeja-slot" style={{background: rev && esCorrecta ? n.color : undefined}}/>
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : ronda.modo === "error" ? (
              <div className="error-wrap">
                <div className="modo-badge" style={{borderColor:"rgba(39,174,96,.55)",color:"#27ae60",background:"rgba(39,174,96,.12)"}}>
                  Modo · Detecta el error
                </div>
                <div className="error-story">
                  <div className="lbl mb8 case-lbl" style={{color:"rgba(39,174,96,.9)"}}>
                    CASO · HALLAZGO OCULTO
                  </div>
                  <div className="qtext">{p.q}</div>
                </div>
                {!elegida && (
                  <div className="error-legend" aria-hidden="true">
                    <span style={{color:"#e74c3c",borderColor:"rgba(231,76,60,.45)",background:"rgba(231,76,60,.12)"}}>🔴 Busca el fallo</span>
                    <span style={{color:"#20bf6b",borderColor:"rgba(32,191,107,.45)",background:"rgba(32,191,107,.12)"}}>🟢 No marques lo correcto</span>
                    <span style={{color:"#f7b731",borderColor:"rgba(247,183,49,.45)",background:"rgba(247,183,49,.12)"}}>🟡 Ignora lo irrelevante</span>
                  </div>
                )}
                <div className="error-opts">
                  {(p.opts || []).map(o => {
                    const rev = !!elegida;
                    const esCorrecta = o.k === p.a;
                    const elegidaEsta = elegida === o.k;
                    let bg = "rgba(255,255,255,.05)";
                    let bd = "rgba(255,255,255,.14)";
                    if (rev) {
                      if (esCorrecta) { bg = "rgba(32,191,107,.22)"; bd = "#20bf6b"; }
                      else if (elegidaEsta) { bg = "rgba(231,76,60,.18)"; bd = "#e74c3c"; }
                      else { bg = "rgba(0,0,0,.18)"; bd = "rgba(255,255,255,.08)"; }
                    }
                    return (
                      <button
                        key={o.k}
                        type="button"
                        className="error-opt"
                        disabled={rev}
                        onClick={() => responder(o.k)}
                        style={{
                          background:bg, borderColor:bd,
                          opacity: rev && !esCorrecta && !elegidaEsta ? .4 : 1,
                          boxShadow: rev && esCorrecta ? "0 0 20px rgba(32,191,107,.45)" : "none",
                        }}
                      >
                        <span className="ek" style={{color: rev && esCorrecta ? "#20bf6b" : "#fff"}}>{o.k}</span>
                        <span className="et">{o.t}</span>
                        {rev && esCorrecta && (
                          <span className="etag" style={{color:"#20bf6b",borderColor:"rgba(32,191,107,.7)"}}>
                            Fallo en la historia ✓
                          </span>
                        )}
                        {rev && elegidaEsta && !esCorrecta && (
                          <span className="etag" style={{color:"#e74c3c",borderColor:"rgba(231,76,60,.7)"}}>
                            Tu respuesta
                          </span>
                        )}
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : ronda.modo === "investiga" ? (
              <div className="inv-wrap">
                <div className="modo-badge" style={{borderColor:"rgba(52,152,219,.55)",color:"#3498db",background:"rgba(52,152,219,.12)"}}>
                  Modo · Investiga
                </div>
                <div className="inv-story">
                  <div className="lbl mb8 case-lbl" style={{color:"rgba(52,152,219,.9)"}}>
                    CASO · INFORMACIÓN INCOMPLETA
                  </div>
                  <div className="qtext">{p.q}</div>
                </div>
                {invInfo && <div className="inv-reveal">🔎 {invInfo}</div>}
                <div className="inv-opts">
                  {(p.pistas || []).map(o => {
                    const rev = !!elegida;
                    const esCorrecta = o.k === p.pista;
                    const elegidaEsta = elegida === o.k;
                    let bg = "rgba(255,255,255,.05)";
                    let bd = "rgba(255,255,255,.14)";
                    if (rev) {
                      if (esCorrecta) { bg = "rgba(32,191,107,.22)"; bd = "#20bf6b"; }
                      else if (elegidaEsta) { bg = "rgba(231,76,60,.18)"; bd = "#e74c3c"; }
                      else { bg = "rgba(0,0,0,.18)"; bd = "rgba(255,255,255,.08)"; }
                    }
                    return (
                      <button key={o.k} type="button" className="inv-opt" disabled={rev || lockedRef.current}
                        onClick={() => responder(o.k)}
                        style={{ background:bg, borderColor:bd, opacity: rev && !esCorrecta && !elegidaEsta ? .4 : 1 }}>
                        <span className="ik">{o.k}</span>
                        <span className="it">{o.t}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : ronda.modo === "decision" ? (
              <div className="dec-wrap">
                <div className="modo-badge" style={{borderColor:"rgba(247,183,49,.55)",color:"#f7b731",background:"rgba(247,183,49,.12)"}}>
                  Modo · Decisión + consecuencia
                </div>
                <div className="dec-guide">
                  <div className="guia-nive" aria-hidden="true">
                    <span>Regla fácil: <b style={{color:"#f7b731"}}>proteger</b> siempre gana a <b style={{color:"#e74c3c"}}>compartir sin cuidado</b></span>
                  </div>
                  <div className="error-hint">⚡ ¿Qué harías para cuidar la información?</div>
                </div>
                <div className="dec-story">
                  <div className="lbl mb8 case-lbl" style={{color:"rgba(247,183,49,.9)"}}>
                    CASO · BATALLA DE DECISIONES
                  </div>
                  <div className="qtext">{p.q}</div>
                </div>
                {decCons && (
                  <div className="dec-cons" style={{
                    borderColor: decCons.ok ? "rgba(32,191,107,.55)" : "rgba(231,76,60,.45)",
                    background: decCons.ok ? "rgba(32,191,107,.14)" : "rgba(231,76,60,.12)",
                    color: decCons.ok ? "#20bf6b" : "#e74c3c",
                  }}>
                    🃏 Consecuencia: {decCons.text}
                  </div>
                )}
                <div className="dec-opts">
                  {(p.acciones || []).map(o => {
                    const rev = !!elegida;
                    const esCorrecta = o.k === p.a;
                    const elegidaEsta = elegida === o.k;
                    let bg = "rgba(255,255,255,.05)";
                    let bd = "rgba(255,255,255,.14)";
                    if (rev) {
                      if (esCorrecta) { bg = "rgba(32,191,107,.22)"; bd = "#20bf6b"; }
                      else if (elegidaEsta) { bg = "rgba(231,76,60,.18)"; bd = "#e74c3c"; }
                      else { bg = "rgba(0,0,0,.18)"; bd = "rgba(255,255,255,.08)"; }
                    }
                    return (
                      <button key={o.k} type="button" className="dec-opt" disabled={rev}
                        onClick={() => responder(o.k)}
                        style={{ background:bg, borderColor:bd, opacity: rev && !esCorrecta && !elegidaEsta ? .4 : 1 }}>
                        <span className="dk">{o.k}</span>
                        <span className="dt">{o.t}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : (
              <div className="opts-grid">
                {KEYS.map(k => {
                  const n = NIVELES[k];
                  const rev = !!elegida;
                  const esCorrecta = k === p.a;
                  const bg = rev ? (esCorrecta ? "rgba(32,191,107,.26)" : "rgba(0,0,0,.18)") : n.bg;
                  const bd = rev ? (esCorrecta ? "#20bf6b" : "rgba(255,255,255,.1)") : n.bd;
                  return (
                    <button key={k} onClick={() => responder(k)} disabled={rev} className="opt-btn"
                      onMouseEnter={e => { if (!rev) e.currentTarget.style.transform = "translateY(-3px)"; }}
                      onMouseLeave={e => { e.currentTarget.style.transform = "none"; }}
                      style={{
                        padding:"clamp(10px,1.8vh,18px) clamp(12px,1.4vw,18px)",
                        background:bg, border:`2px solid ${bd}`, borderRadius:15,
                        cursor: rev ? "default" : "pointer", textAlign:"left", color:"#fff",
                        transition:"all .18s", opacity: rev && !esCorrecta ? .4 : 1,
                        boxShadow: rev && esCorrecta ? "0 0 24px rgba(32,191,107,.6)" : "none"
                      }}>
                      <div className="opt-title" style={{color:n.color}}>
                        {k} · {n.nombre} {rev && esCorrecta ? "✓" : ""}
                      </div>
                      <div className="opt-desc">{n.desc}</div>
                    </button>
                  );
                })}
              </div>
            )}

            {feedback && (
              <div className={feedback.ok ? "fb-ok" : "fb-no"}>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:"clamp(1.15rem,2.6vh,1.55rem)",color:feedback.ok ? "#20bf6b" : "#e74c3c",letterSpacing:".03em"}}>
                  {feedback.ok ? `⚡ ${hero.golpe}` : `☠ ${hero.daño}`}
                </div>
                <div className="fb-msg" style={{marginTop:8}}>{feedback.msg}</div>
              </div>
            )}
          </div>

          {/* DERECHA — Doom */}
          <div className="col lado" style={{minWidth:0}}>
            <div className="lbl center">☠️ El villano</div>
            <div className="doom-card" style={{flex:1,minHeight:0}}>
              <Hero src={IMG.doom} alt="Doctor Doom" className="fit-img" style={{
                borderRadius:12, display:"block", marginBottom:8,
                filter:"drop-shadow(0 0 22px rgba(0,204,0,.4))"
              }}/>
              <div className="doom-meta" style={{flexShrink:0}}>
                <div style={{fontFamily:"'Anton',sans-serif",fontSize:"clamp(.92rem,2.15vh,1.32rem)",color:"#00cc00",letterSpacing:".07em",textShadow:"0 0 12px rgba(0,204,0,.5)"}}>
                  {ronda.poder}
                </div>
                <div className="hpbar"><div className="hpfill" style={{width:`${(hpDoom/3)*100}%`}}/></div>
                <div style={{fontSize:"clamp(.82rem,1.85vh,1.08rem)",color:"rgba(0,204,0,.68)",marginTop:6,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,letterSpacing:".06em"}}>
                  PODER {hpDoom}/3
                </div>
              </div>
            </div>
            <div className="doom-sub" style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:"clamp(.82rem,1.8vh,1.05rem)",color:"rgba(255,255,255,.42)",letterSpacing:".05em",textAlign:"center",lineHeight:1.5,flexShrink:0}}>
              Clasifica bien para<br/>reducir su poder
            </div>
          </div>
        </div>
      </div>
      </div>
    </>
  );
}

/* ═══════════════════════════════════════════════
   PANTALLA 4 — RESULTADO FINAL
═══════════════════════════════════════════════ */
function Resultado({ gano, documento, puntaje, resultados, rondaIdx, startedAt, onReiniciar, skipScore }) {
  useEffect(() => { gano ? SND.win() : SND.doom(); }, []);
  useEffect(() => {
    const endedAt = new Date().toISOString();
    const durationMs = durationMsFrom(startedAt, endedAt);
    markParticipated(documento);
    if (skipScore) return;
    enviarScore({
      documento,
      evento: "fin",
      puntaje,
      respuestasCorrectas: puntaje,
      gano: !!gano,
      durationMs,
      startedAt: startedAt || null,
      endedAt,
      resultados: resultados || [],
      ronda: (rondaIdx ?? 0) + 1,
      rondaIdx: rondaIdx ?? 0,
    });
  }, []);

  return (
    <div className="screen screen-res">
    <div className="card card-flex res-card" style={{maxWidth:680,textAlign:"center"}}>
      {gano && <Confetti/>}

      <Hero src={gano ? IMG.equipo : IMG.doomGana} alt={gano ? "Equipo Ciber Héroes campeón" : "Doom conquista la FCV"} className="res-hero" style={{
        maxWidth: gano ? 520 : 400, borderRadius:16, display:"block", margin:"0 auto clamp(8px,1.6vh,18px)",
        boxShadow: gano ? "0 18px 60px rgba(247,183,49,.25)" : "0 18px 60px rgba(0,204,0,.2)"
      }}/>

      {gano ? (
        <>
          <div className="h1">
            ¡DOOM<br/>
            <span style={{background:"linear-gradient(135deg,#f7b731,#20bf6b)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>DERROTADO!</span>
          </div>
          <div className="tag mt8 mb16">⚡ Trueno salvó la FCV · Eres el Guardián Supremo</div>
          <div className="div"/>
          <div style={{background:"rgba(32,191,107,.07)",border:"1px solid rgba(32,191,107,.22)",borderRadius:14,padding:16,margin:"14px 0"}}>
            <div className="lbl mb4">Respuestas correctas</div>
            <div style={{fontFamily:"'Anton',sans-serif",fontSize:"3.6rem",background:"linear-gradient(135deg,#f7b731,#20bf6b)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>
              {puntaje}
            </div>
            <div className="tag mt4">Documento: {documento}</div>
            {startedAt && (
              <div className="tag mt4">Tiempo: {formatDuration(durationMsFrom(startedAt)).tiempo}</div>
            )}
          </div>
          <p className="body mb20 res-blurb">
            ¡Excelente trabajo! Demostraste que sabes clasificar correctamente los activos de
            información de la institución. El conocimiento es el mejor escudo. 🛡
          </p>
        </>
      ) : (
        <>
          <div className="h1">
            <span style={{background:"linear-gradient(135deg,#00cc00,#006600)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>
              DOOM CONQUISTA<br/>LA FCV
            </span>
          </div>
          <div className="div mt16"/>
          <div style={{background:"rgba(0,100,0,.06)",border:"1px solid rgba(0,204,0,.18)",borderRadius:14,padding:16,margin:"0 0 14px"}}>
            <p style={{fontFamily:"'Anton',sans-serif",fontSize:"1.3rem",color:"#fff",marginBottom:6}}>¡Sigue entrenando, Guardián! 💪</p>
            <div style={{fontFamily:"'Anton',sans-serif",fontSize:"2.8rem",background:"linear-gradient(135deg,#f7b731,#fd9644)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>
              {puntaje}
            </div>
            <div className="tag mt4">Respuestas correctas: {puntaje}</div>
            <div className="tag mt4">Documento: {documento}</div>
            {startedAt && (
              <div className="tag mt4">Tiempo: {formatDuration(durationMsFrom(startedAt)).tiempo}</div>
            )}
            {RONDAS[rondaIdx] && (
              <div className="tag mt4">Quedaste en: {RONDAS[rondaIdx].nombre}</div>
            )}
          </div>

          <div style={{background:"rgba(0,0,0,.35)",borderRadius:12,padding:14,marginBottom:16}}>
            <div className="lbl mb12">Repasa los niveles antes de tu revancha</div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:7}}>
              {KEYS.map(k => {
                const n = NIVELES[k];
                return (
                  <div key={k} style={{background:n.bg,border:`1px solid ${n.bd}`,borderRadius:9,padding:"8px 10px",textAlign:"left"}}>
                    <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:".8rem",color:n.color}}>{k} · {n.nombre}</div>
                    <div style={{fontSize:".66rem",color:"rgba(255,255,255,.6)",marginTop:2,lineHeight:1.4}}>{n.desc}</div>
                  </div>
                );
              })}
            </div>
          </div>
        </>
      )}

      <div style={{display:"flex",flexDirection:"column",gap:10,flexShrink:0}}>
        <button className="btn btn-gold" onClick={() => { SND.click(); onReiniciar(); }}>
          🏠 SALIR AL INICIO
        </button>
      </div>
    </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   APP
═══════════════════════════════════════════════ */
export default function App() {
  const [pantalla,   setPantalla]   = useState("bienvenida");
  const [documento,  setDocumento]  = useState("");
  const [rondaIdx,   setRondaIdx]   = useState(0);
  const [resultados, setResultados] = useState([]);
  const [gano,       setGano]       = useState(false);
  const [puntaje,    setPuntaje]    = useState(0);
  const [introKey,   setIntroKey]   = useState(0);
  const [startedAt,  setStartedAt]  = useState(null);
  const [vidasRestantes, setVidasRestantes] = useState(VIDAS_INICIAL);
  const [scoreEnviado, setScoreEnviado] = useState(false);

  const persist = useCallback((patch) => {
    const doc = patch.documento ?? documento;
    if (!doc) return;
    saveSession({
      documento: doc,
      pantalla: patch.pantalla ?? pantalla,
      rondaIdx: patch.rondaIdx ?? rondaIdx,
      resultados: patch.resultados ?? resultados,
      puntaje: patch.puntaje ?? puntaje,
      vidasRestantes: patch.vidasRestantes ?? vidasRestantes,
      startedAt: patch.startedAt !== undefined ? patch.startedAt : startedAt,
      estado: patch.estado ?? "en_curso",
      gano: patch.gano ?? null,
    });
  }, [documento, pantalla, rondaIdx, resultados, puntaje, vidasRestantes, startedAt]);

  const registrarEvento = useCallback((extra) => {
    if (!documento) return;
    const endedAt = new Date().toISOString();
    enviarScore({
      documento,
      juego: "ciber-heroes-doomsday",
      startedAt: startedAt || null,
      endedAt,
      durationMs: durationMsFrom(startedAt, endedAt),
      resultados,
      vidasRestantes,
      respuestasCorrectas: extra.puntaje ?? extra.respuestasCorrectas ?? 0,
      ...extra,
    });
  }, [documento, startedAt, resultados, vidasRestantes]);

  const cambiarVidas = useCallback((nv) => {
    setVidasRestantes(nv);
    persist({ vidasRestantes: nv });
  }, [persist]);

  const aplicarSesion = (s, doc) => {
    setRondaIdx(s.rondaIdx || 0);
    setResultados(Array.isArray(s.resultados) ? s.resultados : []);
    setPuntaje(s.puntaje || 0);
    setVidasRestantes(typeof s.vidasRestantes === "number" ? s.vidasRestantes : VIDAS_INICIAL);
    setStartedAt(s.startedAt || null);
    setGano(false);
    let dest = s.pantalla === "resultado" ? "juego" : (s.pantalla || "intro");
    if (dest === "bienvenida") dest = "intro";
    if (dest === "intro") setIntroKey(k => k + 1);
    setPantalla(dest);
    saveSession({ ...s, documento: doc, pantalla: dest, estado: "en_curso" });
  };

  const entrar = (d, sesionAbierta) => {
    setDocumento(d);
    if (sesionAbierta && canResumeSession(sesionAbierta)) {
      aplicarSesion(sesionAbierta, d);
      return;
    }
    setRondaIdx(0);
    setResultados([]);
    setPuntaje(0);
    setVidasRestantes(VIDAS_INICIAL);
    setGano(false);
    setStartedAt(null);
    setIntroKey(k => k + 1);
    setPantalla("intro");
    saveSession({
      documento: d,
      pantalla: "intro",
      rondaIdx: 0,
      resultados: [],
      puntaje: 0,
      vidasRestantes: VIDAS_INICIAL,
      startedAt: null,
      estado: "en_curso",
    });
  };

  const iniciar = () => {
    const t0 = new Date().toISOString();
    setStartedAt(t0);
    setRondaIdx(0);
    setResultados([]);
    setPuntaje(0);
    setVidasRestantes(VIDAS_INICIAL);
    setGano(false);
    setPantalla("juego");
    setScoreEnviado(false);
    persist({
      pantalla: "juego",
      rondaIdx: 0,
      resultados: [],
      puntaje: 0,
      vidasRestantes: VIDAS_INICIAL,
      startedAt: t0,
      estado: "en_curso",
    });
  };

  const finRonda = useCallback((res, stats = {}) => {
    const aciertosRonda = Number(stats.aciertos) || 0;
    const preguntasRonda = Number(stats.preguntasRonda) || aciertosRonda;
    const vidas = typeof stats.vidasRestantes === "number" ? stats.vidasRestantes : vidasRestantes;
    const puntajeAcumulado = puntaje + aciertosRonda;
    const ronda = rondaIdx + 1;

    if (res === "loss") {
      setPuntaje(puntajeAcumulado);
      setVidasRestantes(vidas);
      setGano(false);
      setPantalla("resultado");
      registrarEvento({
        evento: "ronda_loss",
        puntaje: puntajeAcumulado,
        gano: false,
        ronda,
        rondaIdx,
        aciertosRonda,
        preguntasRonda,
        vidasRestantes: vidas,
      });
      setScoreEnviado(true);
      markParticipated(documento);
      return;
    }

    const nuevosResultados = [...resultados, "win"];
    setPuntaje(puntajeAcumulado);
    setResultados(nuevosResultados);
    setVidasRestantes(vidas);

    registrarEvento({
      evento: "ronda_ok",
      puntaje: puntajeAcumulado,
      gano: false,
      ronda,
      rondaIdx,
      aciertosRonda,
      preguntasRonda,
      vidasRestantes: vidas,
      resultados: nuevosResultados,
    });

    const sig = rondaIdx + 1;
    if (sig >= RONDAS.length) {
      setGano(true);
      setPantalla("resultado");
      return;
    }
    setRondaIdx(sig);
    setPantalla("juego");
    saveSession({
      documento,
      pantalla: "juego",
      rondaIdx: sig,
      resultados: nuevosResultados,
      puntaje: puntajeAcumulado,
      vidasRestantes: vidas,
      startedAt,
      estado: "en_curso",
    });
  }, [documento, rondaIdx, resultados, puntaje, vidasRestantes, startedAt, registrarEvento]);

  const reiniciar = (opts = {}) => {
    stopVoz();
    if (opts.clear !== false && documento) {
      clearSession(documento);
    }
    setPantalla("bienvenida");
    setDocumento("");
    setRondaIdx(0);
    setResultados([]);
    setPuntaje(0);
    setVidasRestantes(VIDAS_INICIAL);
    setGano(false);
    setStartedAt(null);
  };

  const pantallaFull = true;

  useEffect(() => {
    const html = document.documentElement, body = document.body;
    const prev = {
      hOverflow: html.style.overflow, bOverflow: body.style.overflow,
      hHeight: html.style.height,     bHeight: body.style.height,
      bMargin: body.style.margin,
    };
    if (pantallaFull) {
      html.style.overflow = "hidden"; body.style.overflow = "hidden";
      html.style.height = "100%";     body.style.height = "100%";
      body.style.margin = "0";
    }
    return () => {
      html.style.overflow = prev.hOverflow; body.style.overflow = prev.bOverflow;
      html.style.height = prev.hHeight;     body.style.height = prev.bHeight;
      body.style.margin = prev.bMargin;
    };
  }, [pantallaFull]);

  return (
    <>
      <style>{CSS}</style>
      <div className={`app${pantallaFull ? " app-full" : ""}`}>
        <div className="bg1"/><div className="bg2"/>
        <BgmToggle/>
        <div className="wrap">
          {pantalla === "bienvenida" && <Bienvenida onEntrar={entrar}/>}
          {pantalla === "intro" && (
            <Intro key={introKey}
              onTerminar={() => {
                setPantalla("instrucciones");
                persist({ pantalla: "instrucciones" });
              }}
              onVolver={() => { stopVoz(); setPantalla("bienvenida"); }}
              documento={documento}/>
          )}
          {pantalla === "instrucciones" && (
            <Instrucciones
              onIniciar={iniciar}
              onVolver={() => {
                stopVoz();
                setIntroKey(k => k + 1);
                setPantalla("intro");
                persist({ pantalla: "intro" });
              }}
              documento={documento}/>
          )}
          {pantalla === "juego" && (
            <Juego key={rondaIdx} rondaIdx={rondaIdx} resultados={resultados}
              onFinRonda={finRonda} puntajeTotal={puntaje}
              vidasRestantes={vidasRestantes} onVidasChange={cambiarVidas}/>
          )}
          {pantalla === "resultado" && (
            <Resultado
              gano={gano}
              documento={documento}
              puntaje={puntaje}
              resultados={resultados}
              rondaIdx={rondaIdx}
              startedAt={startedAt}
              skipScore={scoreEnviado}
              onReiniciar={() => reiniciar({ clear: true })}
            />
          )}
        </div>
      </div>
    </>
  );
}
